from pathlib import Path
p = Path('dist/index.html')
s = p.read_text(encoding='utf-8')
s = s.replace('<script src="app.js" defer></script>', '<script src="app.js" defer></script><script src="hold.js" defer></script>')
section = '''<section class="workspace timing" id="timing"><p class="eyebrow" data-en="03 / THINKING ABOUT WAITING?" data-mr="०३ / थांबण्याचा विचार करताय?">03 / THINKING ABOUT WAITING?</p><h2 data-en="Explore a sell-later scenario." data-mr="नंतर विक्रीचा अंदाज तपासा.">Explore a sell-later scenario.</h2><p data-en="You choose the future price. This is arithmetic, not a forecast or advice to store your crop." data-mr="भविष्यातील भाव तुम्ही ठरवा. ही गणना आहे; अंदाज किंवा साठवणुकीचा सल्ला नाही.">You choose the future price. This is arithmetic, not a forecast or advice to store your crop.</p><form id="hold-form"><div class="market-grid"><label><span data-en="Quantity now (quintals)" data-mr="आताचे प्रमाण (क्विंटल)">Quantity now (quintals)</span><input id="hold-quantity" type="number" value="5" min="0.01" max="100000" step="any" required></label><label><span data-en="Price now (₹ per quintal)" data-mr="आताचा भाव (₹ प्रति क्विंटल)">Price now (₹ per quintal)</span><input id="hold-now" type="number" value="2000" min="0" max="10000000" step="any" required></label><label><span data-en="Your assumed later price (₹ per quintal)" data-mr="तुमचा गृहीत नंतरचा भाव (₹ प्रति क्विंटल)">Your assumed later price (₹ per quintal)</span><input id="hold-later" type="number" value="2200" min="0" max="10000000" step="any" required></label><label><span data-en="Extra waiting costs (₹ total)" data-mr="थांबण्याचा अतिरिक्त खर्च (₹ एकूण)">Extra waiting costs (₹ total)</span><input id="hold-cost" type="number" value="500" min="0" max="10000000" step="any" required></label><label><span data-en="Expected loss or spoilage (%)" data-mr="अपेक्षित नुकसान (%)">Expected loss or spoilage (%)</span><input id="hold-loss" type="number" value="5" min="0" max="99" step="any" required></label></div><button class="submit" type="submit" data-en="Explore scenario →" data-mr="पर्यायाचा अंदाज पहा →">Explore scenario →</button></form><div id="hold-result" aria-live="polite" hidden class="result-card"><h3 data-en="Your what-if comparison" data-mr="तुमची गृहीत तुलना">Your what-if comparison</h3><p id="hold-output"></p><p class="fine" data-en="Later amount = remaining quantity × your assumed later price − waiting costs. Break-even ignores selling costs that differ between the two dates. Prices, spoilage and storage risks are uncertain; this does not predict the future." data-mr="नंतरची रक्कम = उरलेले प्रमाण × गृहीत भाव − प्रतीक्षा खर्च. वेगवेगळ्या तारखांचे विक्री खर्च यात समाविष्ट नाहीत. भविष्यातील भाव आणि नुकसान अनिश्चित आहेत.">Later amount = remaining quantity × your assumed later price − waiting costs. Break-even ignores selling costs that differ between the two dates. Prices, spoilage and storage risks are uncertain; this does not predict the future.</p></div></section>'''
s = s.replace('<section class="source">', section + '<section class="source">')
s = s.replace('03 / <span data-en="BEFORE YOU GO"', '04 / <span data-en="BEFORE YOU GO"')
